/**
 * Prepared, audience-friendly answers to the sample questions on the Ask AI tab, written
 * for the presentation from the app's own numbers (DERIVED) on the imported Lazada data
 * (75,618 reviews, Jan 2022 – 2 Jun 2024). They are not generated by AI. The page shows a
 * warning when the data no longer matches `SNAPSHOT`, and "Ask the AI instead" sends the
 * same question to the live provider. Review ids in quotes belong to that import.
 * Safe to import in the browser.
 */

export const SNAPSHOT = { reviews: 75_618, to: "2024-06-02", label: "Lazada reviews, January 2022 to 2 June 2024" };

export interface PreparedAnswer {
  question: string;
  headline: string;
  paragraphs: string[];
  /** Optional ranked list shown between the paragraphs and the quotes. */
  list?: { title: string; items: { label: string; value: string; note?: string }[] };
  quotes: { reviewId: number; text: string; source: string; translation?: string }[];
  caveats: string[];
  /** Filters that open the reviews behind the answer. */
  drill: Record<string, string>;
  /** For answers in Filipino: a one-line English version. */
  english?: string;
}

